using System;using System.Data;using System.Data.SqlClient;using System.Text;using System.Web;namespace schoolms{public partial class student_Fees:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){string enrl=Session["Stud"] as string;if(enrl==null){Response.Redirect("Student_Login.aspx");return;}if(!IsPostBack)Load(enrl);}void Load(string enrl){try{using(SqlConnection c=Db.CreateConnection())using(SqlCommand q=new SqlCommand("SELECT FeeName,Amount,DueDate,Status FROM StudentFees WHERE EnrlNo=@E ORDER BY DueDate",c)){q.Parameters.Add("@E",SqlDbType.NVarChar,30).Value=enrl;c.Open();using(SqlDataReader r=q.ExecuteReader()){StringBuilder b=new StringBuilder("<table><tr><th>Fee</th><th>Amount</th><th>Due Date</th><th>Status</th></tr>");while(r.Read())b.Append("<tr><td>").Append(HttpUtility.HtmlEncode(r.GetString(0))).Append("</td><td>₹").Append(r.GetDecimal(1).ToString("N2")).Append("</td><td>").Append(r.GetDateTime(2).ToString("dd MMM yyyy")).Append("</td><td>").Append(HttpUtility.HtmlEncode(r.GetString(3))).Append("</td></tr>");b.Append("</table>");litFees.Text=b.ToString();}}}catch(SqlException){litFees.Text="<p>Could not load fee details.</p>";}}}}
